CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own profile read" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY "own profile insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY "own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_interview_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'full_name', '')); RETURN NEW; END; $$;
CREATE TRIGGER interview_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_interview_profile();
INSERT INTO public.profiles (id, display_name) SELECT id, coalesce(raw_user_meta_data->>'display_name', raw_user_meta_data->>'full_name', '') FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.interview_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() UNIQUE, messages jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.interview_conversations TO authenticated;
GRANT ALL ON public.interview_conversations TO service_role;
ALTER TABLE public.interview_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own conversation read" ON public.interview_conversations FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "own conversation insert" ON public.interview_conversations FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "own conversation update" ON public.interview_conversations FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
ALTER TABLE public.interview_sessions ADD COLUMN interviewer_name text NOT NULL DEFAULT 'Panel LPDP';
COMMENT ON TABLE public.interview_sessions IS 'Chronological interview segments in one user conversation, not independent threads';
COMMENT ON COLUMN public.interview_sessions.messages IS 'DEPRECATED: messages now in interview_conversations with segment metadata';
INSERT INTO public.interview_conversations(user_id, messages) SELECT s.user_id, coalesce(jsonb_agg(m.value || jsonb_build_object('metadata', jsonb_build_object('segmentId',s.id)) ORDER BY s.created_at, m.ordinality) FILTER (WHERE m.value IS NOT NULL), '[]'::jsonb) FROM public.interview_sessions s LEFT JOIN LATERAL jsonb_array_elements(s.messages) WITH ORDINALITY m(value, ordinality) ON true GROUP BY s.user_id;